/**
 * /platform/pricing/ —— Whaleal Messaging 定价
 *
 * 🔴 2026-11-23 裁决：公开页**不展示金额**。卡片只列档位名、适用对象与功能差异；
 *    `src/data/messagingPricing.js` 的 monthly / yearly / priceNote 仅作内部参考，
 *    禁止渲染到任何公开页（含 /platform/ 概览与 help 文章表格）。
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import PricingLineSwitch from '../../components/PricingLineSwitch';
import { MESSAGING_PRODUCT_NAME, MESSAGING_CONSOLE_URL } from '../../constants/brand';
import { MESSAGING_PLANS, MESSAGING_PRICING_FAQ } from '../../data/messagingPricing';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function MessagingPricing(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={`${MESSAGING_PRODUCT_NAME} pricing — flat, no per-message fees`}
        description={`Four tiers from Free to Ultra, each with unlimited sending. Differences are channel connections, submit rate and log retention. You pay your own provider.`}
        pathname="/platform/pricing/"
        softwareApp={false}
        faqs={MESSAGING_PRICING_FAQ}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: MESSAGING_PRODUCT_NAME, path: '/platform/' },
          { name: 'Pricing', path: '/platform/pricing/' },
        ]} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="platform_pricing.001">Pricing</T></span>
          <h1><T id="platform_pricing.002">You pay your provider for messages. You pay us for the layer.</T></h1>
          <p className="mk-lead"><T id="platform_pricing.003">
            Four tiers, monthly or yearly. Every one includes unlimited sending, the full API and no
            overage bills &mdash; because message volume is not something we bill for. What changes
            between tiers is how many connections you can run, how fast you may submit, and how long
            delivery logs are kept.
          </T></p>
        </header>

        {/* 反向切换：本页是 Messaging 定价，另一条线（Cart）的套餐在 `/pricing/`。
            与 `/pricing/` 底部那条共用同一个组件，文案/样式不各写一份。 */}
        <PricingLineSwitch current="messaging" />

        <div className="mk-scope">
          <T id="platform_pricing.004"><strong>Why there is no per-message price.</strong> {MESSAGING_PRODUCT_NAME} never sells
          message volume. Your messages are sent on your own provider account, at your own rate, on
          your own invoice. A per-message fee from us would mean we were reselling your provider&rsquo;s
          traffic &mdash; which is exactly the model we are not.
        </T></div>

        <section className="mk-section">
          <h2><T id="platform_pricing.005">Compare the tiers</T></h2>
          <div className="mk-price-grid">
            {MESSAGING_PLANS.map((p) => (
              <article className={`mk-price-card${p.highlighted ? ' mk-price-card-hot' : ''}`} key={p.id}>
                {p.highlighted && <span className="mk-card-tag"><T id="platform_pricing.006">Most popular</T></span>}
                <h3>{p.name}</h3>
                <p className="mk-price-for">{p.for}</p>
                <ul className="mk-list">
                  {p.features.map((f) => (
                    <li key={f}>{f}</li>
                  ))}
                </ul>
                <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}><T id="platform_pricing.007">
                  Start on {p.name}</T>
                </a>
              </article>
            ))}
          </div>
          <p className="mk-section-lead"><T id="platform_pricing.008">
            Every tier is a flat subscription, not a per-message fee. Nothing is charged automatically
            when you reach a limit &mdash; you upgrade when you choose to. Open the console to see
            the plans available to your account.
          </T></p>
        </section>

        <section className="mk-section">
          <h2><T id="platform_pricing.009">How the tiers differ</T></h2>
          <p className="mk-section-lead"><T id="platform_pricing.010">
            Tiers differ in three dimensions. Here is what each one measures, and what happens when
            you reach it &mdash; so there are no surprises on the invoice.
          </T></p>
          <table className="mk-table" tabIndex={0}>
            <thead>
              <tr>
                <th><T id="platform_pricing.011">Dimension</T></th>
                <th><T id="platform_pricing.012">What it measures</T></th>
                <th><T id="platform_pricing.013">What happens at the limit</T></th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><T id="platform_pricing.014">Channel connections</T></td>
                <td><T id="platform_pricing.015">How many configured provider connections you hold at once</T></td>
                <td><T id="platform_pricing.016">Add another only after upgrading or removing one</T></td>
              </tr>
              <tr>
                <td><T id="platform_pricing.017">Submit rate (QPS)</T></td>
                <td><T id="platform_pricing.018">How fast you may hand messages to the platform</T></td>
                <td><T id="platform_pricing.019">Requests are paced rather than rejected outright</T></td>
              </tr>
              <tr>
                <td><T id="platform_pricing.020">Log retention</T></td>
                <td><T id="platform_pricing.021">How long delivery metadata stays queryable</T></td>
                <td><T id="platform_pricing.022">Older records age out; sending is unaffected</T></td>
              </tr>
            </tbody>
          </table>
          <div className="mk-scope">
            <T id="platform_pricing.023"><strong>Submit rate vs send pace.</strong> The submit rate is how fast <em>you</em> may
            give us messages. The send pace is how fast <em>we</em> call your provider on a given
            connection &mdash; and it is set by that provider&rsquo;s quota, not by your plan. The
            lower of the two governs.
          </T></div>
        </section>

        <section className="mk-section">
          <h2><T id="platform_pricing.024">Pricing questions</T></h2>
          <dl className="mk-faq">
            {MESSAGING_PRICING_FAQ.map((f) => (
              <div key={f.q}>
                <dt>{f.q}</dt>
                <dd>{f.a}</dd>
              </div>
            ))}
          </dl>
        </section>

        <section className="mk-section">
          <h2><T id="platform_pricing.025">Still deciding?</T></h2>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to={localePath("/integrations/")}><T id="platform_pricing.026">
              See which providers you can connect
            </T></Link>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/faq/")}><T id="platform_pricing.027">
              Read the FAQ
            </T></Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
