/**
 * 双线定价切换条（Cart recovery / Messaging）
 *
 * 为什么需要：`/pricing/` 只有 Cart 套餐、`/platform/pricing/` 只有 Messaging 套餐，
 * 而导航只有一个「Pricing」项指向前者 —— 想买 Messaging 的人在导航上走不通。
 * 两个定价页各放一条切换，读者在任一页都能一步跳到另一条线的价格。
 *
 * 🔴 文案复用导航的 `nav.cart` / `nav.messaging`，**不新增字典键**：
 *    新增键就要在 10 语里各写一遍，而这两条任务名页脚/导航已经定稿，
 *    再起一套译名必然与它们漂移（本页的前身问题正是「同一个东西三个名字」）。
 *
 * 🔴 当前项用 `<span aria-current="page">` 而不是禁用态的 `<a>`：
 *    它不是一个可点的地点，是一句「你正在看这一条线」的陈述。
 *
 * @author 恒哥
 * @since 2026-11-28
 */
import React from 'react';
import { Link } from 'gatsby';
import { useI18n } from '../../i18n';
import './pricingLineSwitch.css';

// `to` 是**这一条线自己的定价页**（不是跳转目标）：组件取 `other`，再用 `other.to` 跳。
// 🔴 别把这里写成「另一条线的地址」—— 会得到「点 Messaging 跳回自己」的结果（已踩过）。
const LINES = {
  cart: { labelKey: 'cart', to: '/pricing/' },
  messaging: { labelKey: 'messaging', to: '/platform/pricing/' },
};

export default function PricingLineSwitch({ current }) {
  const { t, localePath } = useI18n();
  const other = current === 'cart' ? LINES.messaging : LINES.cart;
  const currentKey = current === 'cart' ? LINES.cart.labelKey : LINES.messaging.labelKey;

  return (
    <div className="pricing-line-switch">
      <span className="pricing-line-switch-current" aria-current="page">
        {t.nav[currentKey]}
      </span>
      <Link to={localePath(other.to)} className="pricing-line-switch-link">
        {t.nav[other.labelKey]}
      </Link>
    </div>
  );
}
